  var WINTER_TOPICS = [{"phrases":["grit","gritting","salting","salt spreading","deicing","de icing","icy path","icy paths","icy driveway","icy steps","ice on","black ice"],"a":"Our gritting service is for private residential driveways, paths, steps, ramps and entrances across Preston. Ask about a one-off treatment or planned visits. <a href=\"/?service=Salt%20Spreading%20%26%20Gritting#quote-form\">Get a gritting quote</a>."},{"phrases":["gritting cost","gritting price","gritting prices","price for gritting","cost of gritting","gritting cost per visit","driveway gritting costs","cost to grit","price to grit"],"a":"For domestic gritting, we quote based on the size and surface of the area, access and how often you need a visit. Send your postcode and approximate sizes or photos if you have them. <a href=\"/?service=Salt%20Spreading%20%26%20Gritting#quote-form\">Get a home gritting quote</a>."},{"phrases":["blocked drain","blocked drains","outdoor drain","outside drain","external drain","gully","gullies","downpipe","drain blockage","collapsed drain","drain clearing"],"a":"We clear suitable blocked outdoor drains, gullies and downpipes and assess damaged drain sections. If the blockage keeps coming back, tell us where it happens. <a href=\"/?service=Blocked%20Drains%20%26%20Drainage#quote-form\">Get a drainage quote</a>."},{"phrases":["garden drainage","waterlogged","boggy garden","pooling water","puddles","soakaway","french drain","channel drain","surface water"],"a":"A blocked drain is an issue with a specific pipe, gully or channel. A garden, driveway or yard that repeatedly holds water may need its wider surface drainage assessed. <a href=\"/drainage-repairs\">See garden and surface drainage</a>."},{"phrases":["resealing","reseal","sealant","weatherstrips","weatherstrip","draughty window","draughty windows","draughty door","draughty doors","window seals","window seal","door seals","door seal","rain through the window","water coming through my window","misting between panes"],"a":"Yes, where a failed frame seal or worn weatherstrip is the cause. We check the frame, opening seals and route the water is taking before recommending work. Misting between panes usually indicates a problem with the glazing unit. <a href=\"/?service=Window%20%26%20Door%20Resealing#quote-form\">Get a resealing quote</a>."},{"phrases":["gutter","gutters","guttering","gutter cleaning","gutter clearing","overflowing gutter"],"a":"GreenFix does not offer gutter cleaning or gutter clearing. If you need an exterior repair we do carry out, send the job and your postcode. <a href=\"/#quote-form\">Request a quote</a>."},{"phrases":["storm damage","blown down","fence blew","damaged gate","slipped tile","slipped tiles","roof tiles","loose roof tile"],"a":"We assess storm-damaged fences, gates and roof tiles. Share the postcode and a description so we can check suitable access and arrange a quote. <a href=\"/storm-damage-repairs\">See storm damage repairs</a>."},{"phrases":["loose slabs","loose paving","sunken path","uneven paving","broken paving"],"a":"We assess damaged paths and patios and can quote to repair or relay suitable uneven slabs. <a href=\"/paving-repairs\">See paving repairs</a>."},{"phrases":["winter property","winter maintenance","winter services","winter check","winter checks","winter proof","winterproof"],"a":"Yes. Send your postcode and a short list of the jobs. We can quote for gritting, drainage, resealing or exterior repairs. <a href=\"/winter-property-maintenance-preston\">See all winter services</a>."}];
